//! Outfit colouring (head / body / legs / feet), port of RME `GameSprite::TemplateImage`.
//! Layer 1 of an outfit is a colour mask: yellow = head, red = body, green = legs,
//! blue = feet. Masked pixels of layer 0 are multiplied by the chosen palette colour.

use pme_io::spr::SPRITE_BYTES;

// @generated by tools/gen_outfit_colors.py from RME source/graphics.cpp
pub const OUTFIT_COLORS: [u32; 133] = [
    0xFFFFFF, 0xFFD4BF, 0xFFE9BF, 0xFFFFBF, 0xE9FFBF, 0xD4FFBF, 0xBFFFBF, 0xBFFFD4,
    0xBFFFE9, 0xBFFFFF, 0xBFE9FF, 0xBFD4FF, 0xBFBFFF, 0xD4BFFF, 0xE9BFFF, 0xFFBFFF,
    0xFFBFE9, 0xFFBFD4, 0xFFBFBF, 0xDADADA, 0xBF9F8F, 0xBFAF8F, 0xBFBF8F, 0xAFBF8F,
    0x9FBF8F, 0x8FBF8F, 0x8FBF9F, 0x8FBFAF, 0x8FBFBF, 0x8FAFBF, 0x8F9FBF, 0x8F8FBF,
    0x9F8FBF, 0xAF8FBF, 0xBF8FBF, 0xBF8FAF, 0xBF8F9F, 0xBF8F8F, 0xB6B6B6, 0xBF7F5F,
    0xBFAF8F, 0xBFBF5F, 0x9FBF5F, 0x7FBF5F, 0x5FBF5F, 0x5FBF7F, 0x5FBF9F, 0x5FBFBF,
    0x5F9FBF, 0x5F7FBF, 0x5F5FBF, 0x7F5FBF, 0x9F5FBF, 0xBF5FBF, 0xBF5F9F, 0xBF5F7F,
    0xBF5F5F, 0x919191, 0xBF6A3F, 0xBF943F, 0xBFBF3F, 0x94BF3F, 0x6ABF3F, 0x3FBF3F,
    0x3FBF6A, 0x3FBF94, 0x3FBFBF, 0x3F94BF, 0x3F6ABF, 0x3F3FBF, 0x6A3FBF, 0x943FBF,
    0xBF3FBF, 0xBF3F94, 0xBF3F6A, 0xBF3F3F, 0x6D6D6D, 0xFF5500, 0xFFAA00, 0xFFFF00,
    0xAAFF00, 0x54FF00, 0x00FF00, 0x00FF54, 0x00FFAA, 0x00FFFF, 0x00A9FF, 0x0055FF,
    0x0000FF, 0x5500FF, 0xA900FF, 0xFE00FF, 0xFF00AA, 0xFF0055, 0xFF0000, 0x484848,
    0xBF3F00, 0xBF7F00, 0xBFBF00, 0x7FBF00, 0x3FBF00, 0x00BF00, 0x00BF3F, 0x00BF7F,
    0x00BFBF, 0x007FBF, 0x003FBF, 0x0000BF, 0x3F00BF, 0x7F00BF, 0xBF00BF, 0xBF007F,
    0xBF003F, 0xBF0000, 0x242424, 0x7F2A00, 0x7F5500, 0x7F7F00, 0x557F00, 0x2A7F00,
    0x007F00, 0x007F2A, 0x007F55, 0x007F7F, 0x00547F, 0x002A7F, 0x00007F, 0x2A007F,
    0x54007F, 0x7F007F, 0x7F0055, 0x7F002A, 0x7F0000,
];

#[inline]
fn tint(px: &mut [u8], color: u8) {
    let c = OUTFIT_COLORS.get(color as usize).copied().unwrap_or(OUTFIT_COLORS[0]);
    let (r, g, b) = ((c >> 16) & 0xFF, (c >> 8) & 0xFF, c & 0xFF);
    px[0] = (px[0] as u32 * r / 255) as u8;
    px[1] = (px[1] as u32 * g / 255) as u8;
    px[2] = (px[2] as u32 * b / 255) as u8;
}

/// Colour `base` (RGBA 32x32) using `mask` and `[head, body, legs, feet]`.
pub fn colorize(base: &mut [u8; SPRITE_BYTES], mask: &[u8; SPRITE_BYTES], colors: [u8; 4]) {
    for (px, m) in base.chunks_exact_mut(4).zip(mask.chunks_exact(4)) {
        if px[3] == 0 || m[3] == 0 {
            continue;
        }
        let (r, g, b) = (m[0] != 0, m[1] != 0, m[2] != 0);
        let part = match (r, g, b) {
            (true, true, false) => 0,
            (true, false, false) => 1,
            (false, true, false) => 2,
            (false, false, true) => 3,
            _ => continue,
        };
        tint(px, colors[part]);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_matches_rme() {
        assert_eq!(OUTFIT_COLORS.len(), 133);
        assert_eq!(OUTFIT_COLORS[0], 0xFFFFFF);
        assert_eq!(OUTFIT_COLORS[132], 0x7F0000);
    }

    #[test]
    fn mask_parts() {
        let mut base = [0u8; SPRITE_BYTES];
        let mut mask = [0u8; SPRITE_BYTES];
        // pixel 0: head (yellow mask), pixel 1: feet (blue), pixel 2: unmasked, pixel 3: transparent
        for i in 0..3 {
            base[i * 4..i * 4 + 4].copy_from_slice(&[200, 200, 200, 255]);
        }
        mask[0..4].copy_from_slice(&[255, 255, 0, 255]);
        mask[4..8].copy_from_slice(&[0, 0, 255, 255]);
        mask[12..16].copy_from_slice(&[255, 0, 0, 255]);
        // head = 94 (0xFF0000 red), feet = 88 (0x0000FF blue)
        colorize(&mut base, &mask, [94, 0, 0, 88]);
        assert_eq!(&base[0..4], &[200, 0, 0, 255]);
        assert_eq!(&base[4..8], &[0, 0, 200, 255]);
        assert_eq!(&base[8..12], &[200, 200, 200, 255]);
        assert_eq!(&base[12..16], &[0, 0, 0, 0]);
    }
}
